// CSD_RATIONALE_BEGIN
// Root cause: attempt 72 (best, 53.3%) uses CloseSpanWithinBudget(400) which
// correctly finds the LONGEST complete SQL parse—not the first. However, the
// model's greedy SQL generation terminates at "SELECT col FROM table" (6-10
// tokens), a trivially-complete prefix, before generating WHERE/JOIN/GROUP BY
// clauses. CloseSpanWithinBudget then picks this short complete prefix as best.
//
// Concrete evidence:
//   "What are the notes... with substring 'East'?"
//   Output: "SELECT d.note FROM death d"  (complete at ~6 tokens)
//   Correct: "select note from death where note like '%East%'"  (~12 tokens)
//
// Fix: Insert Phase 3 — a 30-step hard-constrained loop that runs WITHOUT any
// close check, forcing the model past the first trivially-complete parse into
// WHERE/JOIN territory. Then Phase 4 calls CloseSpanWithinBudget(350) to find
// the LONGEST complete prefix in the now-extended SQL.
//
// This directly addresses mode_A (149/152 wrong: fast, low-budget, no WHERE):
// the model is not given a chance to terminate early at a semantically
// incomplete but syntactically valid SQL prefix.
//
// Guidance string unchanged from attempt 72 (proven best; changes hurt 73-75).
// Budget: 5 (preamble) + 1 (force <<) + 30 (phase 3) + 350 (phase 4) = 386 << 900.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the implication
//   is vacuously true on every iteration. The only true-flip is via
//   RenderedEndsWith("<<"), at which point we set currentConstrainedOut := []
//   and IsValidPrefix([]) holds by the method precondition. EOS break leaves
//   insideConstrainedOut=false, implication vacuous.
//
// Phase 2 OpenConstrainedSpan: Runs only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds
//   by precondition. Sets insideConstrainedOut := true.
//
// Phase 3 constrained loop: We only call AppendConstrainedToken when
//   IsTokenValidNext(parser, currentConstrainedOut, next)=true, i.e.,
//   parser.IsValidPrefix(currentConstrainedOut + [next]) holds. The helper's
//   postcondition guarantees the new currentConstrainedOut remains a valid
//   prefix. EOS break leaves state unchanged. The insideConstrainedOut flag
//   stays true throughout (AppendConstrainedToken does not close the span).
//
// Phase 4 CloseSpanWithinBudget: Postcondition directly guarantees
//   (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs 1 step, appends at most 1 token (0 on EOS).
//   Each iteration: steps += 1, |generated| grows by <= 1. Invariant preserved.
//
// Phase 2: OpenConstrainedSpan costs 1 step, appends exactly 1 "<<" token.
//   steps += 1, |generated| += 1. Preserved 1:1.
//
// Phase 3: ConstrainedStep costs 1 step per iteration; steps += 1. AppendConstrainedToken
//   adds exactly 1 token to generated; on EOS or invalid, generated stays same.
//   Either way |generated| grows by at most 1 per iteration and steps grows by 1.
//   Preserved each iteration: |generated| <= |generatedPrefix| + steps.
//   Tokens consumed for EOS (non-visible) still count against steps budget.
//
// Phase 4: closeBudget <= maxSteps - steps_before. CloseSpanWithinBudget
//   postcondition: |cg| <= |generated| + closeBudget. We set steps += closeBudget,
//   so |cg| <= |generatedPrefix| + new_steps. Tokens consumed for dead-end
//   avoidance or EOS that are not visibly appended still count against closeBudget.
//   cost = steps <= maxSteps.
//
// Precondition for Phase 3 ConstrainedStep (|currentConstrainedOut| <= |generated|):
//   After Phase 2: currentConstrainedOut := [], |generated| >= 1. Trivially holds.
//   If Phase 2 skipped: insideConstrained=true on entry guarantees
//   |currentConstrained| <= |generatedPrefix| = |generated|.
//   AppendConstrainedToken preserves: both grow by 1. Maintained throughout.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (at most 5 steps) so model can emit "SQL: <<"
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force << if model has not opened constrained span yet
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate exactly 30 constrained tokens WITHOUT any close check.
// Purpose: force the model past the first trivially-complete SQL parse
// ("SELECT col FROM table", ~6-10 tokens) into WHERE/JOIN/GROUP BY territory
// before Phase 4 finds the LONGEST complete prefix via CloseSpanWithinBudget.
var phase3Budget: nat := 30;
var phase3Steps: nat := 0;
while steps < maxSteps && insideConstrainedOut && phase3Steps < phase3Budget
  invariant 0 <= steps <= maxSteps
  invariant 0 <= phase3Steps <= phase3Budget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
  steps := steps + 1;
  phase3Steps := phase3Steps + 1;
  if next == eosToken {
    break;
  } else {
    var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
    if valid {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: CloseSpanWithinBudget finds the LONGEST complete SQL prefix in
// the now-extended constrained content (which includes Phase 3 tokens that go
// past WHERE/JOIN clauses). Budget=350 gives ample room for complex queries.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat := if remaining <= 350 then remaining else 350;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

